    // So R1 corresponds to y-bending (affecting v, i.e., DOF2), R2 to z-bending (affecting w, i.e., DOF3)

    // SK1 = 0.25*R1*L^2 + EIz/L  (for rotation about z-axis, DOF6 and DOF12)
    // SK2 = 0.25*R2*L^2 + EIy/L  (for rotation about y-axis, DOF5 and DOF11)
    const double SK1 = 0.25 * R1 * LSQ + EIz / L;
    const double SK2 = 0.25 * R2 * LSQ + EIy / L;
    const double SK3 = 0.25 * R1 * LSQ - EIz / L;
    const double SK4 = 0.25 * R2 * LSQ - EIy / L;

    const double LR1 = L * R1 / 2.0;
    const double LR2 = L * R2 / 2.0;

    // Build 12x12 stiffness matrix KE in column-major order as per Fortran
    // But we'll construct it in row-major for output, so we need to place values at (row, col) where
    // row = (k-1) % 12, col = (k-1) / 12 for Fortran index k
    Eigen::Matrix<double, 12, 12, Eigen::RowMajor> KE = Eigen::Matrix<double, 12, 12, Eigen::RowMajor>::Zero();

    // Helper to set value at Fortran index k (1-based)
    auto set_fortran = [&](int k, double val) {
        k--; // to 0-based index
        int row = k % 12;
        int col = k / 12;
        KE(row, col) = val;
    };

    // Set all the values as per Fortran code
    set_fortran(1, AEL);      // (0,0)
    set_fortran(7, -AEL);    // (6,0)
    set_fortran(14, R1);     // (1,1)
    set_fortran(18, LR1);    // (5,1)
    set_fortran(20, -R1);    // (7,1)
    set_fortran(24, LR1);    // (11,1)
    set_fortran(27, R2);     // (2,2)
    set_fortran(29, -LR2);  // (4,2)
    set_fortran(33, -R2);    // (8,2)
    set_fortran(35, -LR2);  // (10,2)
    set_fortran(40, GJL);    // (3,3)
    set_fortran(46, -GJL);   // (9,3)
    set_fortran(51, -LR2);  // (2,4)
    set_fortran(53, SK2);    // (4,4)
    set_fortran(57, LR2);    // (8,4)
    set_fortran(59, SK4);    // (10,4)
    set_fortran(62, LR1);    // (1,5)
    set_fortran(66, SK1);    // (5,5)
    set_fortran(68, -LR1);  // (7,5)
    set_fortran(72, SK3);    // (11,5)
    set_fortran(73, -AEL);  // (0,6)
    set_fortran(79, AEL);    // (6,6)
    set_fortran(86, -R1);    // (1,7)
    set_fortran(90, -LR1);  // (5,7)
    set_fortran(92, R1);     // (7,7)
    set_fortran(96, -LR1);  // (11,7)
    set_fortran(99, -R2);    // (2,8)
    set_fortran(101, LR2);  // (4,8)
    set_fortran(105, R2);    // (8,8)
    set_fortran(107, LR2);  // (10,8)
    set_fortran(112, -GJL); // (3,9)
    set_fortran(118, GJL);  // (9,9)
    set_fortran(123, -LR2); // (2,10)
    set_fortran(125, SK4);  // (4,10)
    set_fortran(129, LR2);  // (8,10)
    set_fortran(131, SK2);  // (10,10)
    set_fortran(134, LR1);  // (1,11)
    set_fortran(138, SK3);  // (5,11)
    set_fortran(140, -LR1); // (7,11)
    set_fortran(144, SK1);  // (11,11)

    // Output as JSON
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 12; ++i) {
        std::cout << "[";
        for (int j = 0; j < 12; ++j) {
            std::cout << format_double(KE(i, j));
            if (j < 11) std::cout << ",";
        }
        std::cout << "]";
        if (i < 11) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}
